/* ---------- batch.js ---------- */

// A batch is one trip to a property: a project name, a running section, and the
// photos filed under it.
//
// Everything lives in KV, and the shape is chosen so the hot path never does a
// read-modify-write. Photos each get their own key, so two album items arriving
// at the same moment cannot overwrite one another — an append-only log that
// `/done` reads back with a prefix list. Only the small meta record is rewritten,
// and only by a command the user typed.
//
// Photo BYTES are never stored. Telegram already holds them and a file_id is
// permanent for the bot, so the batch carries identifiers and nothing heavier.

const CODE_ALPHABET = 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';   // no I/L/O/0/1
const CODE_LEN = 8;
const TTL_DAYS = 14;
const TTL_SECONDS = TTL_DAYS * 86400;

// Which batches still have photos waiting for a caption. The captioning tick
// reads this one key and stops there when it is empty — listing keys to find
// that out costs a list operation every minute of every day, which is how a
// bot that nobody touched used up a month's free allowance in a weekend.
const QUEUE_KEY = 'queue:pending';

async function queueList(env) {
  const raw = await env.BATCHES.get(QUEUE_KEY);
  try { return raw ? JSON.parse(raw) : []; } catch { return []; }
}

async function queueAdd(env, code) {
  const codes = await queueList(env);
  if (codes.includes(code)) return codes;              // already queued: no write
  const next = [...codes, code];
  await env.BATCHES.put(QUEUE_KEY, JSON.stringify(next), { expirationTtl: TTL_SECONDS });
  return next;
}

async function queueRemove(env, code) {
  const codes = await queueList(env);
  if (!codes.includes(code)) return codes;
  const next = codes.filter((c) => c !== code);
  await env.BATCHES.put(QUEUE_KEY, JSON.stringify(next), { expirationTtl: TTL_SECONDS });
  return next;
}

const metaKey = (code) => `batch:${code}:meta`;
const photoKey = (code, id) => `batch:${code}:p:${String(id).padStart(12, '0')}`;
const chatKey = (chatId) => `chat:${chatId}`;

/** Codes are typed in by hand on a phone, so: no ambiguous glyphs, no vowels. */
function newCode() {
  const bytes = crypto.getRandomValues(new Uint8Array(CODE_LEN));
  return [...bytes].map((b) => CODE_ALPHABET[b % CODE_ALPHABET.length]).join('');
}

async function openBatch(env, chatId, projectName) {
  const code = newCode();
  const meta = {
    code,
    chatId,
    project: { name: (projectName || '').trim() },
    section: '',
    status: 'open',
    createdAt: Date.now(),
    closedAt: null,
    count: 0,
  };
  await putMeta(env, meta);
  await env.BATCHES.put(chatKey(chatId), code, { expirationTtl: TTL_SECONDS });
  return meta;
}

const putMeta = (env, meta) =>
  env.BATCHES.put(metaKey(meta.code), JSON.stringify(meta), { expirationTtl: TTL_SECONDS });

async function getMeta(env, code) {
  const raw = await env.BATCHES.get(metaKey(code));
  return raw ? JSON.parse(raw) : null;
}

/** The batch this chat is currently filing into, if any. */
async function activeBatch(env, chatId) {
  const code = await env.BATCHES.get(chatKey(chatId));
  if (!code) return null;
  const meta = await getMeta(env, code);
  return meta && meta.status === 'open' ? meta : null;
}

async function setSection(env, meta, title) {
  meta.section = String(title || '').trim().toUpperCase();
  await putMeta(env, meta);
  return meta;
}

/**
 * File one photo. `id` is the Telegram message_id, which also orders the batch:
 * album items can reach the webhook out of order, but their message ids do not
 * lie about the order they were sent in.
 */
/**
 * The fields anything other than captioning needs. KV can carry this alongside
 * the key, so a listing returns it without a read per photo — which is the
 * difference between a batch costing one request and costing one per photo.
 */
function summary(rec) {
  return {
    id: rec.id,
    section: rec.section,
    caption: rec.aiCaption || rec.caption || '',
    captionSource: rec.aiCaption ? 'ai' : (rec.caption ? 'typed' : ''),
    tried: rec.aiCaption !== undefined || !!rec.caption,
    takenAt: rec.takenAt,
    takenSource: rec.takenSource,
    w: rec.w,
    h: rec.h,
  };
}

/** Write a photo, keeping its summary on the key. Exported for the captioner,
 * which already holds the record and has no reason to read it back first. */
const putPhoto = (env, code, rec) =>
  env.BATCHES.put(photoKey(code, rec.id), JSON.stringify(rec), {
    expirationTtl: TTL_SECONDS,
    metadata: summary(rec),
  });

async function addPhoto(env, meta, photo) {
  const rec = {
    id: photo.id,
    fileId: photo.fileId,
    aiFileId: photo.aiFileId || photo.fileId,
    section: meta.section || 'GENERAL',
    caption: photo.caption || '',
    takenAt: photo.takenAt,
    takenSource: photo.takenSource || 'telegram',
    w: photo.w || 0,
    h: photo.h || 0,
    mediaGroupId: photo.mediaGroupId || '',
    // Filled in later by the captioning pass; absent means "not looked at yet".
    aiCaption: undefined,
  };
  await putPhoto(env, meta.code, rec);
  // Only a photo that needs a caption puts its batch in the queue.
  if (!rec.caption) await queueAdd(env, meta.code);
  return rec;
}

/**
 * Every photo's summary, in the order they were sent, from the key listing
 * alone — a page of a thousand keys is one request, however big the job.
 *
 * Nothing on a hot path may read photos one by one: a 200-photo batch would
 * then cost 200 reads every time a photo is served or the chat is acked, and a
 * Worker is cut off long before that.
 */
async function listSummaries(env, code) {
  const out = [];
  let cursor;
  do {
    const page = await env.BATCHES.list({ prefix: `batch:${code}:p:`, cursor });
    for (const k of page.keys) {
      if (k.metadata) out.push(k.metadata);
      else out.push({ id: Number(k.name.split(':').pop()), section: 'GENERAL', caption: '', tried: false });
    }
    cursor = page.list_complete ? null : page.cursor;
  } while (cursor);
  out.sort((a, b) => a.id - b.id);
  return out;
}

/** One photo's full record. */
async function getPhoto(env, code, id) {
  const raw = await env.BATCHES.get(photoKey(code, id));
  return raw ? JSON.parse(raw) : null;
}

/** Every full record. Only for a pass that genuinely needs all of them. */
async function listPhotos(env, code) {
  const out = [];
  for (const s of await listSummaries(env, code)) {
    const rec = await getPhoto(env, code, s.id);
    if (rec) out.push(rec);
  }
  return out;
}

async function updatePhoto(env, code, id, patch) {
  const current = await getPhoto(env, code, id);
  if (!current) return null;
  const rec = { ...current, ...patch };
  await putPhoto(env, code, rec);
  return rec;
}

async function dropPhoto(env, code, id) {
  await env.BATCHES.delete(photoKey(code, id));
}

async function closeBatch(env, meta) {
  meta.status = 'closed';
  meta.closedAt = Date.now();
  await putMeta(env, meta);
  await env.BATCHES.delete(chatKey(meta.chatId));
  return meta;
}

/**
 * Retire a batch. The meta and chat keys go first, because those are what make
 * the code work — once they are gone the batch is gone as far as anyone can
 * tell. The photo keys are then cleared within a budget rather than all at
 * once; every key already carries a 14-day expiry, so anything left over is
 * swept up by KV itself instead of costing this request a read apiece.
 */
async function deleteBatch(env, meta, budget = 40) {
  await queueRemove(env, meta.code);
  await env.BATCHES.delete(metaKey(meta.code));
  await env.BATCHES.delete(chatKey(meta.chatId));
  const summaries = await listSummaries(env, meta.code);
  for (const s of summaries.slice(0, budget)) {
    await env.BATCHES.delete(photoKey(meta.code, s.id));
  }
}

/**
 * What the app downloads: sections in the order they were first used, each with
 * its photos. No bytes — every photo is fetched separately from /api/photo, so a
 * manifest stays a couple of kilobytes however big the day was.
 */
function manifest(meta, photos) {
  const order = [];
  const bySection = new Map();
  photos.forEach((p, i) => {
    const title = p.section || 'GENERAL';
    if (!bySection.has(title)) { bySection.set(title, []); order.push(title); }
    bySection.get(title).push({
      n: i + 1,
      id: p.id,
      caption: p.aiCaption || p.caption || '',
      captionSource: p.aiCaption ? 'ai' : (p.caption ? 'typed' : ''),
      takenAt: p.takenAt,
      takenSource: p.takenSource,
      w: p.w,
      h: p.h,
    });
  });
  return {
    format: 'instareport-intake',
    version: 1,
    code: meta.code,
    project: meta.project,
    status: meta.status,
    createdAt: meta.createdAt,
    closedAt: meta.closedAt,
    total: photos.length,
    pending: photos.filter((p) => (p.tried !== undefined ? !p.tried : (p.aiCaption === undefined && !p.caption))).length,
    sections: order.map((title) => ({ title, photos: bySection.get(title) })),
  };
}

/** Per-section counts, for the /list reply. */
function tally(photos) {
  const counts = new Map();
  for (const p of photos) counts.set(p.section, (counts.get(p.section) || 0) + 1);
  return [...counts.entries()];
}

const batch = { queueList, queueAdd, queueRemove, newCode, openBatch, getMeta, activeBatch, setSection, summary, addPhoto, listSummaries, getPhoto, listPhotos, updatePhoto, dropPhoto, closeBatch, deleteBatch, manifest, tally, TTL_SECONDS, putMeta, putPhoto };

/* ---------- telegram.js ---------- */

// The slice of the Bot API this bot needs. Nothing here buffers a photo: the
// bytes go from Telegram to the app as a stream, which is what keeps the Worker
// inside the free plan's CPU budget.

const API = 'https://api.telegram.org';

async function call(env, method, body) {
  const res = await fetch(`${API}/bot${env.TG_TOKEN}/${method}`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(body),
  });
  const data = await res.json().catch(() => ({}));
  if (!data.ok) throw new Error(`${method} failed: ${data.description || res.status}`);
  return data.result;
}

const sendMessage = (env, chatId, text, extra = {}) =>
  call(env, 'sendMessage', { chat_id: chatId, text, ...extra });

const getFile = (env, fileId) => call(env, 'getFile', { file_id: fileId });

/**
 * Open the original bytes for a file_id. A file_path is short-lived, so it is
 * fetched fresh every time rather than cached; a file_id itself does not expire,
 * which is what lets Telegram be the photo store.
 */
async function openFile(env, fileId) {
  const file = await getFile(env, fileId);
  const res = await fetch(`${API}/file/bot${env.TG_TOKEN}/${file.file_path}`);
  if (!res.ok) throw new Error(`file download failed (${res.status})`);
  return res;
}

/** Post the manifest into the chat as a real file, for the fallback path. */
async function sendDocument(env, chatId, filename, text, caption) {
  const form = new FormData();
  form.set('chat_id', String(chatId));
  if (caption) form.set('caption', caption);
  // Blob + a filename argument rather than `new File`, which is not reliably a
  // global in the Workers runtime.
  form.append('document', new Blob([text], { type: 'application/json' }), filename);
  const res = await fetch(`${API}/bot${env.TG_TOKEN}/sendDocument`, { method: 'POST', body: form });
  const data = await res.json().catch(() => ({}));
  if (!data.ok) throw new Error(`sendDocument failed: ${data.description || res.status}`);
  return data.result;
}

/** Tell Telegram where to deliver updates. Saves the user a curl. */
const setWebhook = (env, url, secret) => call(env, 'setWebhook', {
  url,
  secret_token: secret,
  allowed_updates: ['message', 'channel_post'],
});

/** Who this token belongs to — used to confirm setup worked. */
const getMe = (env) => call(env, 'getMe', {});

/**
 * Pick the variant nearest a target width. Telegram ships several sizes of every
 * photo, so the right one for the model is already there — no resizing needed,
 * which a Worker could not afford to do anyway.
 */
function pickSize(sizes, targetPx) {
  if (!sizes || !sizes.length) return null;
  const sorted = [...sizes].sort((a, b) => a.width - b.width);
  return sorted.find((s) => s.width >= targetPx) || sorted[sorted.length - 1];
}

/** The largest variant, which is what the report should print. */
const largest = (sizes) =>
  (sizes && sizes.length ? [...sizes].sort((a, b) => b.width - a.width)[0] : null);

const tg = { openFile, sendDocument, pickSize, sendMessage, getFile, setWebhook, getMe, largest };

/* ---------- caption.js ---------- */

// Captions photos with Gemini, so a batch arrives already written up and the
// office only reviews.
//
// This is the browser assistant's logic (js/ai.js) with the browser taken out:
// same system prompt, same model ladder, same library hinting. Two deliberate
// differences, both forced by where it runs:
//
//   1. One photo per request, not eight. The app batches to save tokens, but a
//      Worker pays for base64 in CPU time and the free plan's budget is per
//      invocation. One small photo is comfortably inside it whatever the exact
//      limit turns out to be; eight would be a gamble.
//   2. No canvas to downscale with. Telegram already ships several sizes of
//      every photo, so the bot records the one nearest a Gemini tile when the
//      photo arrives and that is what gets sent.
//
// Nothing here is on the critical path. Captioning happens twice over:
//
//   * as each photo arrives, so a small job is written up by the time the last
//     photo is forwarded and there is nothing to wait for;
//   * from a cron tick, which sweeps up what the arrival pass could not do —
//     Gemini's free tier allows about fifteen requests a minute, so a couple of
//     hundred photos forwarded in one go will always spill over.
//
// A photo that fails simply arrives blank.



const HOST = 'https://generativelanguage.googleapis.com/v1beta/models';
const LADDER = ['gemini-2.5-flash-lite', 'gemini-2.5-flash'];
const COOLDOWN_MS = 90_000;
const HINTS = 24;                 // library entries shown to the model
const COOLDOWN_KEY = 'ai:cooldown';

const SYSTEM =
  'Caption photos for a building defect report. Reply with the caption only. '
  + 'UPPERCASE, 4-7 words, plain QA/QC wording a contractor can action. '
  + 'Reuse a caption from the library when one fits. '
  + 'No defect visible: describe the item factually. Technical terms stay in English. '
  // These photos are stamped by the site team's camera app. The date is not the
  // defect and must never become the caption.
  + 'Ignore any date or time printed on the photo.';

const clean = (t) => String(t || '').replace(/^["'\s]+|["'.\s]+$/g, '').toUpperCase().slice(0, 90);

/* ------------------------- the library ------------------------- */

/**
 * The office's caption library if it has been pushed, otherwise the one built
 * into this file from js/captions.js. Either way the model is hinted with the
 * same wording the report will print.
 */
async function library(env) {
  const raw = await env.BATCHES.get('lib:captions');
  if (raw) {
    try {
      const lib = JSON.parse(raw);
      if (Array.isArray(lib) && lib.length) return lib;
    } catch { /* fall through to the built-in */ }
  }
  return DEFAULT_LIBRARY;
}

// Which caption groups suit which room. Ported from affinity() in
// js/captions.js — the app ranks by usage as well, which a Worker has no sight
// of, so this is the part that carries over.
const AFFINITY = {
  BATH: ['Plumbing', 'Tiling', 'Door & Window'],
  KITCHEN: ['Plumbing', 'Tiling', 'Electrical'],
  YARD: ['Plumbing', 'Metalwork'],
  'CAR PORCH': ['Metalwork', 'General'],
  EXTERNAL: ['Wall & Ceiling', 'Metalwork', 'Roofing'],
  STAIR: ['Tiling', 'Wall & Ceiling'],
  BEDROOM: ['Wall & Ceiling', 'Door & Window', 'Electrical'],
  LIVING: ['Tiling', 'Electrical', 'Door & Window'],
  DINING: ['Tiling', 'Electrical'],
  ROOF: ['Roofing', 'Wall & Ceiling'],
  CEILING: ['Roofing', 'Wall & Ceiling'],
  DB: ['Electrical'],
};

/** The captions worth the tokens for this room, most likely first. Named as in
 * js/ai.js, where the same job is done against the app's own library. */
function libraryHint(lib, sectionTitle) {
  const sec = String(sectionTitle || '').toUpperCase();
  const suited = new Set();
  for (const key of Object.keys(AFFINITY)) {
    if (sec.includes(key)) AFFINITY[key].forEach((g) => suited.add(g));
  }
  const flat = lib.flatMap((g) => g.items.map((t) => ({ group: g.group, text: t })));
  const ranked = [
    ...flat.filter((c) => suited.has(c.group)),
    ...flat.filter((c) => !suited.has(c.group)),
  ];
  return ranked.slice(0, HINTS).map((c) => c.text.replace(/\n/g, ' / ')).join(' | ');
}

/* ------------------------- talking to Gemini ------------------------- */

/** Chunked, because a byte-at-a-time loop over a photo is the expensive way. */
function base64(bytes) {
  let bin = '';
  const CHUNK = 0x8000;
  for (let i = 0; i < bytes.length; i += CHUNK) {
    bin += String.fromCharCode.apply(null, bytes.subarray(i, i + CHUNK));
  }
  return btoa(bin);
}

/** Models rate-limited recently, so a tick does not walk into the same wall. */
async function cooling(env) {
  const raw = await env.BATCHES.get(COOLDOWN_KEY);
  const map = raw ? JSON.parse(raw) : {};
  const now = Date.now();
  return {
    ready: (m) => (map[m] || 0) < now,
    rest: async (m) => {
      map[m] = now + COOLDOWN_MS;
      await env.BATCHES.put(COOLDOWN_KEY, JSON.stringify(map), { expirationTtl: 600 });
    },
  };
}

/**
 * One caption from one model.
 *
 * `plain` drops the two optional pieces some models refuse outright — the
 * system instruction, which Google also calls the developer instruction, and
 * the thinking budget. The rules are not lost: they go at the front of the
 * prompt, which every model reads.
 */
async function ask(env, model, imageB64, prompt, plain = false) {
  const parts = [{ inline_data: { mime_type: 'image/jpeg', data: imageB64 } }];
  if (plain) parts.push({ text: `${SYSTEM}\n\n${prompt}` });
  else parts.push({ text: prompt });

  const body = {
    contents: [{ role: 'user', parts }],
    generationConfig: {
      temperature: 0.1,
      maxOutputTokens: 32,
      // Flash reasons before answering out of the same budget, which can leave
      // a short caption with nothing left to say.
      ...(!plain && /flash/i.test(model) ? { thinkingConfig: { thinkingBudget: 0 } } : {}),
    },
    ...(plain ? {} : { systemInstruction: { parts: [{ text: SYSTEM }] } }),
  };

  const res = await fetch(`${HOST}/${encodeURIComponent(model)}:generateContent`, {
    method: 'POST',
    headers: { 'content-type': 'application/json', 'x-goog-api-key': env.GEMINI_KEY },
    body: JSON.stringify(body),
  });

  if (!res.ok) {
    let detail = '';
    try { detail = (await res.json()).error?.message || ''; } catch { /* non-JSON */ }
    const err = new Error(`${res.status} ${detail}`.trim());
    err.status = res.status;
    // A rate limit or a model this key cannot see: step down the ladder.
    err.step = res.status === 429 || res.status === 404;
    // The model is fine but will not take part of the request: same model,
    // simpler request.
    err.plain = res.status === 400 && !plain
      && /instruction|thinking|not enabled|not supported|unsupported/i.test(detail);
    throw err;
  }

  const data = await res.json();
  const reply = data.candidates?.[0]?.content?.parts || [];
  return clean(reply.map((p) => p.text).filter(Boolean).join(''));
}

/* ------------------------- the pass ------------------------- */

/**
 * Caption up to `max` photos that have none. Returns what it did, which is what
 * the cron log and the manual trigger report.
 */
async function captionPending(env, max = 6, { rescan = false } = {}) {
  if (!env.GEMINI_KEY) return { ok: false, reason: 'GEMINI_KEY is not set', done: 0 };

  // One read, and usually the end of it. This runs every couple of minutes
  // forever, so an idle tick has to cost as close to nothing as possible — in
  // particular it must not list keys, which is the scarcest free allowance.
  const codes = rescan ? await openCodes(env) : await batch.queueList(env);
  if (!codes.length) return { ok: true, done: 0, failed: 0, remaining: 0, idle: true, errors: [] };

  const lib = await library(env);
  const cool = await cooling(env);
  const out = { ok: true, done: 0, failed: 0, remaining: 0, errors: [] };

  for (const code of codes) {
    // Summaries first, so finding the handful still to do costs one request
    // rather than one per photo. Only the ones actually being captioned are
    // then read in full.
    const waiting = (await batch.listSummaries(env, code)).filter((p) => !p.tried);
    if (!waiting.length) {
      // Nothing left here: take it off the queue so later ticks cost one read.
      await batch.queueRemove(env, code);
      continue;
    }
    // A rescan is what you run when the queue has lost something — photos filed
    // before the queue existed, or a write that did not land. Put it back, so
    // the fix is permanent and nobody has to run this twice.
    if (rescan) await batch.queueAdd(env, code);

    for (const s of waiting) {
      if (out.done + out.failed >= max) { out.remaining++; continue; }
      try {
        const photo = await batch.getPhoto(env, code, s.id);
        if (!photo) continue;
        await captionOne(env, code, photo, lib, cool);
        out.done++;
      } catch (err) {
        out.failed++;
        if (out.errors.length < 3) out.errors.push(err.message);
        // Mark it tried so one unreadable photo cannot block the queue forever
        // — but not when the only thing wrong was a rate limit, which is the
        // ordinary outcome of forwarding two hundred photos at once and clears
        // by itself. That one is left pending for the next tick.
        if (!err.retry) await batch.updatePhoto(env, code, s.id, { aiCaption: '' });
      }
    }
  }
  return out;
}

async function captionOne(env, code, photo, lib, cool) {
  // The variant nearest a Gemini tile, chosen when the photo arrived. Older
  // batches only have the full-size one.
  const file = await tg.openFile(env, photo.aiFileId || photo.fileId);
  const bytes = new Uint8Array(await file.arrayBuffer());
  const prompt = `Room: ${photo.section || 'unspecified'}\nLibrary: ${libraryHint(lib, photo.section)}`;
  const img = base64(bytes);

  let last = null;
  for (const model of LADDER) {
    if (!cool.ready(model)) continue;
    for (const plain of [false, true]) {
      try {
        const text = await ask(env, model, img, prompt, plain);
        if (text) {
          // Written straight from the record in hand: reading it back to patch
          // it would cost an extra operation on every photo of every batch.
          await batch.putPhoto(env, code, { ...photo, aiCaption: text, aiModel: model });
          return text;
        }
        last = new Error('empty reply');
        break;
      } catch (err) {
        last = err;
        if (err.step) await cool.rest(model);
        if (err.plain) continue;    // same model, without the parts it refused
        if (!err.step) return Promise.reject(err);   // a real error: no model helps
        break;
      }
    }
  }
  const err = last || new Error('every model is resting');
  // Rate limits and resting models clear on their own, so the caller should
  // leave the photo pending rather than writing it off.
  if (!last || last.step) err.retry = true;
  throw err;
}

/**
 * Caption one photo the moment it is filed, from the webhook that filed it.
 *
 * This is what makes an ordinary job — a few dozen photos — arrive already
 * written up, with no tick to wait for. It gives up cheaply and silently: the
 * photo is already on the queue, so anything not done here is done by the next
 * tick, and nothing about the bot's reply depends on it.
 */
async function captionOnArrival(env, code, rec) {
  if (!env.GEMINI_KEY || !rec || rec.caption) return null;

  const cool = await cooling(env);
  // Gemini said "too fast" a moment ago and the rest of the burst is still
  // coming. Stop before reading the library or downloading anything: every
  // photo behind this one would otherwise pay for the same refusal.
  if (!LADDER.some((m) => cool.ready(m))) return null;

  // Outside the try on purpose: only a failure to caption should write the photo
  // off, never a storage hiccup reading the library.
  const lib = await library(env);
  try {
    return await captionOne(env, code, rec, lib, cool);
  } catch (err) {
    if (!err.retry) await batch.updatePhoto(env, code, rec.id, { aiCaption: '' });
    return null;
  }
}

/** Every batch that still exists — the slow way, for a rescan. */
async function openCodes(env) {
  const codes = [];
  let cursor;
  do {
    const page = await env.BATCHES.list({ prefix: 'batch:', cursor });
    for (const k of page.keys) {
      const m = /^batch:([A-Z0-9]+):meta$/.exec(k.name);
      if (m) codes.push(m[1]);
    }
    cursor = page.list_complete ? null : page.cursor;
  } while (cursor);
  return codes;
}

/* ---------- bot.js ---------- */

// What the site team sees. Every reply is one short line, because this is read
// one-handed, outdoors, on a phone.




const HELP = [
  'Insta Report intake',
  '',
  '/project 23 JALAN KERUING — start a new batch',
  '/sec KITCHEN — file the photos that follow under this section',
  '/list — what is in the batch so far',
  '/undo — remove the last photo',
  '/done — finish and get the import code',
  '/cancel — throw the batch away',
  '',
  'Forward photos here from the site group. The date they were originally sent',
  'is kept, so forwarding a week of work at once still files it by the right day.',
].join('\n');

/** Parse "/sec KITCHEN" or "/sec@mybot KITCHEN" into ['sec', 'KITCHEN']. */
function parseCommand(text) {
  const m = /^\/([a-z_]+)(?:@\w+)?(?:\s+([\s\S]*))?$/i.exec((text || '').trim());
  return m ? [m[1].toLowerCase(), (m[2] || '').trim()] : [null, ''];
}

async function handleUpdate(env, update, ctx) {
  const msg = update.message || update.channel_post;
  if (!msg) return;

  const chatId = msg.chat && msg.chat.id;
  if (!allowed(env, chatId)) return;                  // silence, not an error page

  if (msg.photo || msg.document) return filePhoto(env, msg, chatId);

  const [cmd, rest] = parseCommand(msg.text);
  if (!cmd) return;

  switch (cmd) {
    case 'start':
    case 'help':
      return tg.sendMessage(env, chatId, HELP);
    case 'project':
      return startProject(env, chatId, rest);
    case 'sec':
    case 'section':
      return chooseSection(env, chatId, rest);
    case 'list':
      return listBatch(env, chatId);
    case 'undo':
      return undo(env, chatId);
    case 'done':
      return done(env, chatId, ctx);
    case 'cancel':
      return cancel(env, chatId);
    default:
      return tg.sendMessage(env, chatId, `Unknown command. ${'/help'} for the list.`);
  }
}

/** An empty allowlist means "not configured yet" and accepts nothing. */
function allowed(env, chatId) {
  const list = String(env.ALLOWED_CHATS || '').split(',').map((s) => s.trim()).filter(Boolean);
  return list.length > 0 && list.includes(String(chatId));
}

async function startProject(env, chatId, name) {
  if (!name) return tg.sendMessage(env, chatId, 'Name it: /project 23 JALAN KERUING');
  const open = await batch.activeBatch(env, chatId);
  if (open) {
    return tg.sendMessage(env, chatId,
      `A batch for ${open.project.name || 'this chat'} is still open. /done it first, or /cancel.`);
  }
  const meta = await batch.openBatch(env, chatId, name);
  return tg.sendMessage(env, chatId,
    `Batch open — ${meta.project.name}\nNow: /sec CAR PORCH, then send the photos.`);
}

async function chooseSection(env, chatId, title) {
  const meta = await batch.activeBatch(env, chatId);
  if (!meta) return tg.sendMessage(env, chatId, 'No batch open. Start with /project <name>.');
  if (!title) return tg.sendMessage(env, chatId, 'Name it: /sec KITCHEN');
  await batch.setSection(env, meta, title);
  return tg.sendMessage(env, chatId, `Section: ${meta.section}`);
}

/**
 * File a photo against the batch's current section.
 *
 * Telegram re-encodes anything sent as a photo and drops its EXIF, so the send
 * time is the best capture time available and is marked as such. A photo sent as
 * a document keeps its original bytes — the import side reads EXIF out of those.
 */
async function filePhoto(env, msg, chatId) {
  const meta = await batch.activeBatch(env, chatId);
  if (!meta) return;                                  // chatter before /project: ignore

  const asDocument = !!(msg.document && /^image\//.test(msg.document.mime_type || ''));
  if (!msg.photo && !asDocument) return;              // a PDF or a voice note is not a defect

  const big = asDocument ? null : tg.largest(msg.photo);
  // Telegram ships several sizes. Keep the biggest for the report and note the
  // one nearest a Gemini tile, so captioning never downloads more than it needs
  // — a Worker cannot resize, but it can choose.
  const small = asDocument ? null : tg.pickSize(msg.photo, Number(env.CAPTION_PX) || 768);
  const rec = await batch.addPhoto(env, meta, {
    id: msg.message_id,
    fileId: asDocument ? msg.document.file_id : big.file_id,
    aiFileId: asDocument ? msg.document.file_id : (small || big).file_id,
    caption: (msg.caption || '').trim(),
    takenAt: sentAt(msg) * 1000,
    takenSource: asDocument ? 'file' : 'telegram',
    w: asDocument ? 0 : big.width,
    h: asDocument ? 0 : big.height,
    mediaGroupId: msg.media_group_id || '',
  });

  // Write it up now, in the same breath as filing it. Telegram delivers every
  // photo as its own request, so this costs one Gemini call per request rather
  // than a queue anywhere, and a few dozen photos are captioned by the time the
  // last one is forwarded.
  //
  // Started here but returned rather than handed to ctx.waitUntil: this whole
  // function ALREADY runs inside the webhook's waitUntil, after the response
  // has gone back to Telegram, and a waitUntil called from there is not
  // something the runtime promises to honour — it can be dropped on the floor
  // without a word. Part of the returned promise, it cannot be. It runs
  // alongside the ack rather than delaying it, and failing changes nothing:
  // the photo is on the queue and the tick sweeps up the rest.
  const captioning = captionOnArrival(env, meta.code, rec).catch(() => {});

  // Album items arrive as separate updates seconds apart; acking each one would
  // bury the chat, so only the first of a group speaks.
  if (!rec.mediaGroupId || firstOfGroup(rec, msg)) {
    const photos = await batch.listSummaries(env, meta.code);
    const n = photos.filter((p) => p.section === rec.section).length;
    await tg.sendMessage(env, chatId, `✓ ${rec.section} · ${n}`,
      { disable_notification: true });
  }
  return captioning;
}

/**
 * When the photo was originally sent, not when it reached the bot. Photos are
 * forwarded from the site group in batches, so the forward time is just when
 * the office got round to it — a week of work would otherwise land on today.
 *
 * forward_origin is the current field and forward_date the older one; both are
 * read so this works whichever the Bot API sends. Nothing changes for a photo
 * sent to the bot directly.
 */
function sentAt(msg) {
  const origin = msg.forward_origin || {};
  return origin.date || msg.forward_date || msg.date || Math.floor(Date.now() / 1000);
}

// Telegram gives no "first of album" flag; the caption only rides on the first
// item, which is a good enough proxy and costs nothing to check.
const firstOfGroup = (rec, msg) => !!msg.caption || !rec.mediaGroupId;

async function listBatch(env, chatId) {
  const meta = await batch.activeBatch(env, chatId) || await lastClosed(env, chatId);
  if (!meta) return tg.sendMessage(env, chatId, 'No batch open. Start with /project <name>.');
  const photos = await batch.listSummaries(env, meta.code);
  if (!photos.length) return tg.sendMessage(env, chatId, `${meta.project.name} — no photos yet.`);
  const lines = batch.tally(photos).map(([sec, n]) => `${sec} — ${n}`);
  return tg.sendMessage(env, chatId,
    `${meta.project.name}\n${lines.join('\n')}\n${photos.length} photo(s) total.`);
}

async function undo(env, chatId) {
  const meta = await batch.activeBatch(env, chatId);
  if (!meta) return tg.sendMessage(env, chatId, 'No batch open.');
  const photos = await batch.listSummaries(env, meta.code);
  const last = photos[photos.length - 1];
  if (!last) return tg.sendMessage(env, chatId, 'Nothing to undo.');
  await batch.dropPhoto(env, meta.code, last.id);
  return tg.sendMessage(env, chatId, `Removed one from ${last.section}. ${photos.length - 1} left.`);
}

async function cancel(env, chatId) {
  const meta = await batch.activeBatch(env, chatId);
  if (!meta) return tg.sendMessage(env, chatId, 'No batch open.');
  await batch.deleteBatch(env, meta);
  return tg.sendMessage(env, chatId, 'Batch discarded.');
}

async function done(env, chatId, ctx) {
  const meta = await batch.activeBatch(env, chatId);
  if (!meta) return tg.sendMessage(env, chatId, 'No batch open.');
  const photos = await batch.listSummaries(env, meta.code);
  if (!photos.length) {
    await batch.deleteBatch(env, meta);
    return tg.sendMessage(env, chatId, 'Empty batch — discarded.');
  }
  await batch.closeBatch(env, meta);
  // So /list still answers after the batch is closed.
  await env.BATCHES.put(`chat:${chatId}:last`, meta.code, { expirationTtl: batch.TTL_SECONDS });

  const lines = batch.tally(photos).map(([sec, n]) => `${sec} — ${n}`);
  await tg.sendMessage(env, chatId, [
    `${meta.project.name} — done.`,
    ...lines,
    '',
    `Import code: ${meta.code}`,
    'Open Insta Report > + > Import from Telegram.',
  ].join('\n'));

  // The fallback: the same manifest as a file, for when typing a code is the
  // wrong shape of effort. It is metadata only, so it stays tiny.
  const doc = JSON.stringify(batch.manifest(meta, photos), null, 2);
  const send = tg.sendDocument(env, chatId, `${meta.code}.instareport.json`, doc,
    'Open this in Insta Report if you would rather not type the code.');
  if (ctx && ctx.waitUntil) ctx.waitUntil(send.catch(() => {}));
  else await send.catch(() => {});
}

/** /list after /done still answers, which is what someone checking would expect. */
async function lastClosed(env, chatId) {
  const code = await env.BATCHES.get(`chat:${chatId}:last`);
  return code ? batch.getMeta(env, code) : null;
}

/* ---------- index.js ---------- */

// Insta Report intake — the whole server side.
//
// It is a postbox, not a database: Telegram keeps the photo bytes, the app keeps
// the report, and this holds a few kilobytes of "which photo, which section"
// until the app collects them. That is what keeps it inside free plans with no
// payment method on the account — see worker/README.md.





const json = (data, status = 200) => new Response(JSON.stringify(data), {
  status,
  headers: { 'content-type': 'application/json', ...cors() },
});

// The app is served from GitHub Pages, so every API call is cross-origin.
const cors = () => ({
  'access-control-allow-origin': '*',
  'access-control-allow-headers': 'content-type',
  'access-control-allow-methods': 'GET,POST,OPTIONS',
});

export default {
  /** The safety net. Photos are captioned as they arrive (see filePhoto in
   * bot.js); this sweeps up the ones Gemini was too busy to take, a few at a
   * time, so a burst is written up by the time the office opens it. An idle
   * tick reads one key and stops. */
  async scheduled(event, env, ctx) {
    ctx.waitUntil(captionPending(env, Number(env.CAPTION_PER_TICK) || 6)
      .then((r) => console.log('caption tick', JSON.stringify(r)))
      .catch((err) => console.error('caption tick failed', err)));
  },

  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const path = url.pathname.replace(/\/+$/, '') || '/';

    if (request.method === 'OPTIONS') return new Response(null, { headers: cors() });

    try {
      // `build` is a fingerprint of the pasted file, printed by worker/build.mjs.
      // "Did my paste actually land?" has cost more time here than any bug, and
      // this answers it in one look.
      if (path === '/health') return json({ ok: true, build: buildStamp() });

      // Everything the captioner looks at, in one place. Nothing here is a
      // secret — codes, counts and whether a key is set, never its value — but
      // it lists keys, so it is behind the webhook secret and never automatic.
      if (path === '/api/status') {
        if (url.searchParams.get('secret') !== env.TG_WEBHOOK_SECRET) {
          return json({ ok: false, error: 'That secret does not match TG_WEBHOOK_SECRET.' }, 401);
        }
        return json(await status(env));
      }

      if (path === '/tg/webhook' && request.method === 'POST') {
        // Telegram is the only caller that knows this header. Anything else is
        // someone poking at the URL.
        if (request.headers.get('x-telegram-bot-api-secret-token') !== env.TG_WEBHOOK_SECRET) {
          return json({ error: 'no' }, 401);
        }
        const update = await request.json();
        // Answer immediately and do the work after: Telegram retries an update
        // it thinks failed, which would file every photo twice.
        ctx.waitUntil(handleUpdate(env, update, ctx).catch((err) => console.error(err)));
        return json({ ok: true });
      }

      // Visited once, by hand, from a browser: it points Telegram at this very
      // Worker. The bot token stays here rather than going into a command line
      // or the address bar.
      if (path === '/tg/register') {
        if (url.searchParams.get('secret') !== env.TG_WEBHOOK_SECRET) {
          return json({ ok: false, error: 'That secret does not match TG_WEBHOOK_SECRET.' }, 401);
        }
        return register(env, url);
      }

      // Run the captioner by hand, for testing setup without waiting for a tick.
      if (path === '/api/caption/run') {
        if (url.searchParams.get('secret') !== env.TG_WEBHOOK_SECRET) {
          return json({ ok: false, error: 'That secret does not match TG_WEBHOOK_SECRET.' }, 401);
        }
        // ?rescan=1 finds work by scanning every key, for when the queue has
        // been lost. It costs list operations, so it is never automatic.
        return json(await captionPending(env, Number(url.searchParams.get('max')) || 6,
          { rescan: url.searchParams.get('rescan') === '1' }));
      }

      // The office's caption library, pushed from the app so the bot hints the
      // model with the same wording the report prints.
      if (path === '/api/library' && request.method === 'POST') {
        if (url.searchParams.get('secret') !== env.TG_WEBHOOK_SECRET) {
          return json({ ok: false, error: 'That secret does not match TG_WEBHOOK_SECRET.' }, 401);
        }
        const lib = await request.json().catch(() => null);
        if (!Array.isArray(lib) || !lib.length) return json({ ok: false, error: 'Expected a caption library array.' }, 400);
        await env.BATCHES.put('lib:captions', JSON.stringify(lib));
        return json({ ok: true, groups: lib.length, captions: lib.reduce((n, g) => n + (g.items || []).length, 0) });
      }

      const manifestMatch = /^\/api\/batch\/([A-Z0-9]{4,16})$/.exec(path);
      if (manifestMatch) return serveManifest(env, manifestMatch[1]);

      const photoMatch = /^\/api\/photo\/([A-Z0-9]{4,16})\/(\d+)$/.exec(path);
      if (photoMatch) return servePhoto(env, photoMatch[1], Number(photoMatch[2]));

      const claimMatch = /^\/api\/batch\/([A-Z0-9]{4,16})\/claim$/.exec(path);
      if (claimMatch && request.method === 'POST') return claim(env, claimMatch[1]);

      return json({ error: 'not found' }, 404);
    } catch (err) {
      console.error(err);
      return json({ error: 'server error' }, 500);
    }
  },
};

/** The bundle's fingerprint, or 'dev' when running from src/ under Node. */
const buildStamp = () => (typeof BUILD_STAMP === 'string' ? BUILD_STAMP : 'dev');

/**
 * Why captioning is or is not happening, answered from the stored state rather
 * than from what anyone believes is deployed.
 *
 * Every mystery so far has come down to one of these four: the wrong file is
 * pasted, the key is missing, the queue disagrees with what is actually
 * waiting, or a batch is not there at all. So: report all four together, and
 * say plainly which it is.
 */
async function status(env) {
  const queue = await batch.queueList(env);
  const codes = [];
  let cursor;
  do {
    const page = await env.BATCHES.list({ prefix: 'batch:', cursor });
    for (const k of page.keys) {
      const m = /^batch:([A-Z0-9]+):meta$/.exec(k.name);
      if (m) codes.push(m[1]);
    }
    cursor = page.list_complete ? null : page.cursor;
  } while (cursor);

  const batches = [];
  for (const code of codes.slice(0, 20)) {
    const meta = await batch.getMeta(env, code);
    const photos = await batch.listSummaries(env, code);
    batches.push({
      code,
      project: meta && meta.project ? meta.project.name : '',
      status: meta ? meta.status : 'missing',
      photos: photos.length,
      waiting: photos.filter((p) => !p.tried).length,
      queued: queue.includes(code),
    });
  }

  const stranded = batches.filter((b) => b.waiting > 0 && !b.queued);
  const cooldown = await env.BATCHES.get('ai:cooldown');

  return {
    ok: true,
    build: buildStamp(),
    geminiKeySet: !!env.GEMINI_KEY,
    perTick: Number(env.CAPTION_PER_TICK) || 6,
    queue,
    batches,
    cooling: cooldown ? JSON.parse(cooldown) : {},
    diagnosis: diagnose(env, batches, stranded),
  };
}

function diagnose(env, batches, stranded) {
  if (!env.GEMINI_KEY) {
    return 'GEMINI_KEY is not set on this Worker, so nothing will ever be captioned. '
      + 'Settings > Variables and Secrets > add it as a Secret, then Deploy.';
  }
  const waiting = batches.reduce((n, b) => n + b.waiting, 0);
  if (!waiting) return 'Nothing is waiting for a caption.';
  if (stranded.length) {
    return `${waiting} photo(s) are waiting but ${stranded.length} batch(es) are not on the `
      + 'queue, so the tick will never look at them. This happens to photos filed before the '
      + 'queue existed. Run /api/caption/run?secret=...&rescan=1 once to pick them up.';
  }
  return `${waiting} photo(s) are waiting and queued. If they stay that way, the cron trigger `
    + 'is not firing: check Settings > Trigger Events for */2 * * * *.';
}

/**
 * Point Telegram at this Worker. This is the one step done by hand during
 * setup, so it says exactly what is wrong rather than falling into the generic
 * 500 — it is already behind the secret, so there is nothing to hide here.
 */
async function register(env, url) {
  const token = String(env.TG_TOKEN || '').trim();
  const secret = String(env.TG_WEBHOOK_SECRET || '');

  if (!token) {
    return json({ ok: false, error: 'TG_TOKEN is not set. Add it in the Worker\u2019s '
      + 'Settings > Variables and Secrets, as a Secret, then Deploy and try again.' }, 400);
  }

  // Deliberately no local check of what a token or a secret should look like.
  // Telegram is the authority on its own credentials, and a guess at the format
  // here would sit between the user and a perfectly good token. Ask Telegram,
  // and if it says no, describe what is stored so the bad paste is visible.
  const hook = `${url.origin}/tg/webhook`;
  try {
    await tg.setWebhook(env, hook, secret);
  } catch (err) {
    return json({
      ok: false,
      error: `Telegram refused: ${err.message}`,
      webhook: hook,
      check: describe(token, secret),
      hint: hintFor(err.message, token, secret),
    }, 502);
  }
  const me = await tg.getMe(env).catch(() => ({}));
  return json({ ok: true, bot: me.username || null, webhook: hook });
}

/**
 * The shape of the stored values, never the values themselves. Enough to spot a
 * paste that picked up a label, a quote, a line break or an invisible
 * character — safe to paste into a chat when asking for help.
 */
function describe(token, secret) {
  const colon = token.indexOf(':');
  const common = (v) => {
    // Name the odd characters by code point. A lookalike dash is invisible in a
    // dashboard field and is the usual reason a token that looks perfect fails.
    const odd = [...new Set([...v].filter((c) => c < ' ' || c > '~'))]
      .map((c) => 'U+' + c.codePointAt(0).toString(16).toUpperCase().padStart(4, '0'));
    return {
      length: v.length,
      hasWhitespace: /\s/.test(v),
      hasQuotes: /['"]/.test(v),
      nonAscii: odd.length > 0,
      nonAsciiCharacters: odd,
    };
  };
  return {
    TG_TOKEN: {
      ...common(token),
      hasColon: colon > 0,
      digitsBeforeColon: colon > 0 && /^\d+$/.test(token.slice(0, colon)),
      charsAfterColon: colon > 0 ? token.length - colon - 1 : 0,
    },
    TG_WEBHOOK_SECRET: {
      ...common(secret),
      // Telegram only accepts these in a secret_token.
      onlyLettersNumbersDashUnderscore: /^[A-Za-z0-9_-]{1,256}$/.test(secret),
    },
  };
}

// The characters that masquerade as a hyphen or an underscore in a token.
const LOOKALIKES = {
  '\u2010': 'a hyphen (U+2010) rather than a plain -',
  '\u2011': 'a non-breaking hyphen (U+2011) rather than a plain -',
  '\u2012': 'a figure dash (U+2012) rather than a plain -',
  '\u2013': 'an en dash (\u2013) rather than a plain -',
  '\u2014': 'an em dash (\u2014) rather than a plain -',
  '\u2212': 'a minus sign (U+2212) rather than a plain -',
  '\u200B': 'an invisible zero-width space',
  '\u200E': 'an invisible left-to-right mark',
  '\u200F': 'an invisible right-to-left mark',
  '\uFEFF': 'an invisible byte-order mark',
};

/** Turn the common failures into the actual next action. */
function hintFor(message, token, secret) {
  // Check this before anything else: the value can be the perfect length and
  // shape and still fail on one character that looks right and is not.
  const odd = [...token].find((c) => c < ' ' || c > '~');
  if (odd) {
    const name = LOOKALIKES[odd];
    return 'TG_TOKEN contains a character that is not a plain letter, digit, colon, underscore '
      + `or hyphen${name ? ` \u2014 it has ${name}` : ''}. This happens when the token is copied `
      + 'through something that auto-formats, turning a hyphen into a dash. Copy it again '
      + 'straight from BotFather\u2019s message (/mybots > your bot > API Token), replace '
      + 'TG_TOKEN, and Deploy.';
  }
  if (/secret_token/i.test(message)) {
    return 'Change TG_WEBHOOK_SECRET to letters, numbers, underscore and hyphen only, '
      + 'Deploy, then visit this address again with the new value.';
  }
  if (/unauthorized|not found/i.test(message)) {
    if (!/^\d+:/.test(token)) {
      return 'What is stored in TG_TOKEN does not start with digits and a colon, so it is '
        + 'probably not the token — check you did not swap it with another value, or paste a '
        + 'label like "TG_TOKEN=" along with it.';
    }
    return 'The token is the right shape but Telegram does not recognise it. Re-copy it from '
      + 'BotFather (/mybots > your bot > API Token), replace TG_TOKEN, and Deploy.';
  }
  if (/url/i.test(message)) {
    return 'Telegram could not accept this Worker address. It must be public https, which a '
      + 'workers.dev address is — check the Worker is deployed.';
  }
  return 'Send me the whole of this reply; it carries no secret values.';
}

async function serveManifest(env, code) {
  const meta = await batch.getMeta(env, code);
  if (!meta) return json({ error: 'unknown code' }, 404);
  // Summaries, not full records: a 200-photo batch is a couple of requests
  // rather than 200, which is the difference between working and being cut off.
  return json(batch.manifest(meta, await batch.listSummaries(env, code)));
}

/**
 * Stream one photo straight from Telegram to the app. Nothing is buffered and
 * nothing is re-encoded, so a 4MB photo costs the same CPU as a 40KB one.
 */
async function servePhoto(env, code, id) {
  const meta = await batch.getMeta(env, code);
  if (!meta) return json({ error: 'unknown code' }, 404);
  const photo = await batch.getPhoto(env, code, id);
  if (!photo) return json({ error: 'unknown photo' }, 404);

  const upstream = await tg.openFile(env, photo.fileId);
  return new Response(upstream.body, {
    headers: {
      'content-type': upstream.headers.get('content-type') || 'image/jpeg',
      'cache-control': 'private, max-age=3600',
      ...cors(),
    },
  });
}

/** The app has the photos now, so the batch can go. */
async function claim(env, code) {
  const meta = await batch.getMeta(env, code);
  if (!meta) return json({ error: 'unknown code' }, 404);
  await batch.deleteBatch(env, meta);
  return json({ ok: true });
}

